  assert.ok(kpis.every((kpi) => /Held: Depeg status is unknown/.test(text(kpi))));
  assert.match(text(page.el("pd-modal-status")), /Held/); assert.match(text(page.el("pd-modal-status")), /Depeg status is unknown/);
  assert.equal(page.el("pd-pdf").disabled, true);
  assert.match(text(page.el("pd-rate-chart")), /No rates were produced/);
