test("the assessment dialog: focus moves in, Tab wraps, Escape closes, and focus returns to the Simulate that opened it", async () => {
  const page = await ready();
  const opener = page.simulate(1);
  await opener.click(); await settle();
  assert.equal(page.dialog.open, true);
  assert.equal(lastFocus(), page.el("pd-dialog-title"), "focus lands on the dialog's heading");
  // Tab wraps from the last control to the first and Shift+Tab the other way.
  const order = []; walk(page.dialog, (node) => { if (["button", "summary"].includes(node.tagName) && !node.disabled && node.getAttribute("tabindex") !== "-1" && !node.hidden) order.push(node); });
  const first = order[0]; const last = order.at(-1);
  assert.equal(first, page.el("pd-close")); assert.equal(last, page.el("pd-pdf"));
  const forward = page.keyIn(page.dialog, last, "Tab"); assert.equal(forward.prevented, true); assert.equal(lastFocus(), first);
  const backward = page.keyIn(page.dialog, first, "Tab", { shiftKey: true }); assert.equal(backward.prevented, true); assert.equal(lastFocus(), last);
  const middle = page.keyIn(page.dialog, page.el("pd-tab-quote"), "Tab"); assert.equal(middle.prevented, false, "Tab inside the dialog moves on normally");
  const escape = page.key(page.dialog, "Escape");
  assert.equal(escape.prevented, true); assert.equal(escape.stopped, true); assert.equal(page.dialog.open, false);
  assert.equal(lastFocus(), opener, "focus returns to the button that opened it");
  // Evaluate opens it again and the Evaluate button gets focus back; so does Close and a click on the backdrop.
  await page.edit(0).click(); await settle();
  await page.el("pd-evaluate").click(); await settle();
  assert.equal(page.dialog.open, true);
  await page.el("pd-close").click(); assert.equal(page.dialog.open, false); assert.equal(lastFocus(), page.el("pd-evaluate"));
  await page.el("pd-evaluate").click(); await settle();
  page.dialog.fire("pointerdown", { target: page.dialog }); page.dialog.fire("click", { target: page.dialog });
  assert.equal(page.dialog.open, false, "a click on the backdrop closes it");
  await page.el("pd-evaluate").click(); await settle();
  page.dialog.fire("click", { target: page.el("pd-kpis") });
  assert.equal(page.dialog.open, true, "a click inside does not");
  const cancel = { prevented: false }; cancel.preventDefault = () => { cancel.prevented = true; }; page.dialog.fire("cancel", cancel);
  assert.equal(cancel.prevented, true); assert.equal(page.dialog.open, false);
  // The last-assessment button reopens it, and closing returns focus there.
  const reopen = page.buttons(page.el("pd-last-result"), "Open assessment")[0]; await reopen.click();
  assert.equal(page.dialog.open, true); page.key(page.dialog, "Escape");
  assert.equal(lastFocus(), page.buttons(page.el("pd-last-result"), "Open assessment")[0], "focus returns to the Open assessment button");
});

